// ─── Two DataSource configuration ───
@Configuration
public class MultiDataSourceConfig {

    @Primary
    @Bean @ConfigurationProperties("spring.datasource.primary")
    DataSource primaryDataSource() { return DataSourceBuilder.create().build(); }

    @Bean @ConfigurationProperties("spring.datasource.secondary")
    DataSource secondaryDataSource() { return DataSourceBuilder.create().build(); }

    @Primary
    @Bean
    PlatformTransactionManager primaryTxManager(
            @Qualifier("primaryDataSource") DataSource ds, EntityManagerFactory emf) {
        return new JpaTransactionManager(emf);
    }

    @Bean("secondaryTxManager")
    PlatformTransactionManager secondaryTxManager(
            @Qualifier("secondaryDataSource") DataSource ds) {
        return new DataSourceTransactionManager(ds);
    }
}

